package com.flashsale.activity;
import org.junit.jupiter.api.Test;import java.time.OffsetDateTime;import static org.junit.jupiter.api.Assertions.*;
class ActivityStateMachineTest { @Test void requiresPreheatBeforeStart(){var now=OffsetDateTime.now();var m=new ActivityStateMachine();var initial=m.create(new Activity(0,"sale",1,10,5,0,1,now.minusMinutes(1),now.plusMinutes(1),null,false,1));assertThrows(IllegalArgumentException.class,()->m.start(initial,now));var preheated=m.preheat(initial);assertEquals(ActivityStatus.ACTIVE,m.start(preheated,now).status());} @Test void cancelOnlyBeforeStart(){var now=OffsetDateTime.now();var m=new ActivityStateMachine();var a=m.create(new Activity(0,"sale",1,10,5,0,1,now,now.plusMinutes(1),null,false,1));assertEquals(ActivityStatus.CANCELLED,m.cancel(a).status());}}
